CREATE TABLE companies (id UUID PRIMARY KEY, name TEXT NOT NULL, stage TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE founders (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), email TEXT NOT NULL, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id, email));
CREATE TABLE alfred_tasks (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), requested_by UUID NOT NULL REFERENCES founders(id), objective TEXT NOT NULL, status TEXT NOT NULL, thread_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE TABLE company_events (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), type TEXT NOT NULL, actor TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}'::jsonb, occurred_at TIMESTAMPTZ NOT NULL);
CREATE TABLE actions (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), task_id UUID NOT NULL REFERENCES alfred_tasks(id), planned_action_id UUID NOT NULL, tool_name TEXT NOT NULL, authority TEXT NOT NULL, status TEXT NOT NULL, result JSONB, error JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE approvals (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), task_id UUID NOT NULL REFERENCES alfred_tasks(id), action_id UUID, proposed_action JSONB NOT NULL, reason TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL, requested_at TIMESTAMPTZ NOT NULL, decided_at TIMESTAMPTZ, decided_by UUID REFERENCES founders(id));
CREATE TABLE memories (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), scope TEXT NOT NULL, content TEXT NOT NULL, source JSONB NOT NULL, confidence NUMERIC NOT NULL CHECK (confidence >= 0 AND confidence <= 1), provenance TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE decisions (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), summary TEXT NOT NULL, rationale TEXT, decided_by UUID REFERENCES founders(id), decided_at TIMESTAMPTZ NOT NULL, review_at TIMESTAMPTZ);
CREATE TABLE commitments (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id), owner_id UUID NOT NULL REFERENCES founders(id), description TEXT NOT NULL, due_at TIMESTAMPTZ, status TEXT NOT NULL, source TEXT NOT NULL);
CREATE INDEX alfred_tasks_company_status_idx ON alfred_tasks(company_id, status);
CREATE INDEX actions_task_idx ON actions(task_id);
CREATE INDEX memories_company_scope_idx ON memories(company_id, scope);
